    private static final BigDecimal MAX_ORDER_TOTAL = Money.of("1000.00");

    @Override
    public String code() {
        return "BANK_SLIP";
    }

    @Override
    public boolean acceptsInstallments(int installments) {
        return installments == 1;
    }

