import java.net.URI;
import java.net.http.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public class Race {
    static HttpClient http = HttpClient.newHttpClient();
    static String post(String url, String body) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create(url)).header("Content-Type","application/json")
            .POST(HttpRequest.BodyPublishers.ofString(body)).build(), HttpResponse.BodyHandlers.ofString()).body();
    }
    static String get(String url) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create(url)).GET().build(), HttpResponse.BodyHandlers.ofString()).body();
    }
    static String field(String json, String f) { Matcher m = Pattern.compile("\"" + f + "\":\"?([^\",}]*)").matcher(json); return m.find() ? m.group(1) : null; }
    public static void main(String[] a) throws Exception {
        int rounds = Integer.parseInt(a[0]); String sku = a[1];
        int ok = 0, bad = 0, winA = 0, winB = 0, minStock = Integer.MAX_VALUE;
        ExecutorService ex = Executors.newFixedThreadPool(2);
        for (int r = 0; r < rounds; r++) {
            String[] ids = new String[2];
            for (int i = 0; i < 2; i++) {
                String cpf = String.format("8%d%09d", i, r + Long.parseLong(a[2]));
                String body = "{\"customer\":{\"cpf\":\"" + cpf + "\",\"email\":\"r@x.com\"},\"items\":[{\"sku\":\"" + sku + "\",\"quantity\":1}],\"zipCode\":\"01310100\",\"region\":\"SOUTH\",\"shippingMethod\":\"STORE_PICKUP\",\"paymentMethod\":\"PIX\",\"installments\":1,\"clubTier\":\"SILVER\"}";
                ids[i] = field(post("http://localhost:8081/orders", body), "id");
            }
            CyclicBarrier barrier = new CyclicBarrier(2);
            String paidAt = java.time.Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString();
            List<Future<String>> fs = new ArrayList<>();
            for (int i = 0; i < 2; i++) {
                int port = i == 0 ? 8081 : 8082; String id = ids[i];
                fs.add(ex.submit(() -> { barrier.await(); return post("http://localhost:" + port + "/orders/" + id + "/payment", "{\"transactionId\":\"TX-" + id + "\",\"paidAt\":\"" + paidAt + "\"}"); }));
            }
            String ra = fs.get(0).get(), rb = fs.get(1).get();
            String sa = field(get("http://localhost:8081/orders/" + ids[0]), "status"), sb = field(get("http://localhost:8081/orders/" + ids[1]), "status");
            int stock = Integer.parseInt(field(get("http://localhost:8081/products/" + sku), "stock"));
            minStock = Math.min(minStock, stock);
            int paid = (sa.equals("PAID") ? 1 : 0) + (sb.equals("PAID") ? 1 : 0);
            if (paid == 1 && stock == 0) ok++; else { bad++; System.out.println("round " + r + " A=" + ra + " B=" + rb + " stock=" + stock); }
            if (sa.equals("PAID")) winA++; if (sb.equals("PAID")) winB++;
            for (int i = 0; i < 2; i++) if (field(get("http://localhost:8081/orders/" + ids[i]), "status").equals("PAID")) post("http://localhost:8081/orders/" + ids[i] + "/cancellation", "");
        }
        ex.shutdown();
        System.out.println("rounds=" + rounds + " ok=" + ok + " bad=" + bad + " winA(8081)=" + winA + " winB(8082)=" + winB + " minStock=" + minStock
            + " finalStock=" + field(get("http://localhost:8081/products/" + sku), "stock"));
    }
}
EOF
